import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <cute/algorithm/copy.hpp>

using namespace cute;

// GEMM: C[M,N] = A[M,K] @ B[K,N]
// A is stored row-major (M,K): stride (K,1)
// B is stored row-major (K,N): stride (N,1)  -> viewed as (N,K) with stride (1,N)
// C is stored row-major (M,N): stride (N,1)
template <class TA, class TB, class TC, int BLK_M, int BLK_N, int BLK_K>
__global__ static void
gemm_device(int M, int N, int K,
            TA const* A, int strideA_M,
            TB const* B, int strideB_N,
            TC      * C, int strideC_M)
{
  // Full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(strideA_M, Int<1>{})); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, strideB_N)); // (N,K) view of (K,N) row-major
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(strideC_M, Int<1>{})); // (M,N)

  auto cta_tiler = make_shape(Int<BLK_M>{}, Int<BLK_N>{}, Int<BLK_K>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{}); // (BLK_M, BLK_K, k)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X, _1, _1>{}); // (BLK_N, BLK_K, k)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1, X>{}); // (BLK_M, BLK_N)

  // Pad the leading (contiguous) dimension of the shared-memory tiles by a
  // non-multiple-of-32 skew to avoid shared-memory bank conflicts that would
  // otherwise occur because BLK_M/BLK_N are exact multiples of the warp size.
  constexpr int SKEW = 4;
  __shared__ TA smemA[BLK_K * (BLK_M + SKEW)];
  __shared__ TB smemB[BLK_K * (BLK_N + SKEW)];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<BLK_M>{}, Int<BLK_K>{}),
                          make_stride(Int<1>{}, Int<BLK_M + SKEW>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<BLK_N>{}, Int<BLK_K>{}),
                          make_stride(Int<1>{}, Int<BLK_N + SKEW>{}));

  // Thread layouts for loading (product must equal blockDim.x = 256)
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}), make_stride(Int<16>{}, Int<1>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{});

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  int K_TILE_MAX = size<2>(tAgA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    copy(AutoVectorizingCopyWithAssumedAlignment<128>{}, tAgA(_, _, k_tile), tAsA);
    copy(AutoVectorizingCopyWithAssumedAlignment<128>{}, tBgB(_, _, k_tile), tBsB);
    __syncthreads();
    gemm(tCsA, tCsB, tCrC);
    // For this workload K is very small (often exactly BLK_K), so the
    // k-loop typically runs a single iteration. Only issue the trailing
    // synchronization when there is actually another k-tile to stage,
    // eliminating a redundant barrier per CTA in the common single-tile
    // case (keeps the small-K dimension fully resident in the CTA with
    // no unnecessary loop/sync overhead).
    if (k_tile + 1 < K_TILE_MAX) {
      __syncthreads();
    }
  }

  axpby(1.0f, tCrC, 0.0f, tCgC);
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);
  int N = (int)B_c.size(1);
  TORCH_CHECK((int)B_c.size(0) == K, "Inner dimensions must match");

  constexpr int BLK_M = 128;
  constexpr int BLK_N = 128;
  constexpr int BLK_K = 32;

  TORCH_CHECK(M % BLK_M == 0, "M must be divisible by ", BLK_M);
  TORCH_CHECK(N % BLK_N == 0, "N must be divisible by ", BLK_N);
  TORCH_CHECK(K % BLK_K == 0, "K must be divisible by ", BLK_K);

  auto C = torch::empty({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  dim3 dimBlock(256);
  dim3 dimGrid(M / BLK_M, N / BLK_N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gemm_device<float, float, float, BLK_M, BLK_N, BLK_K><<<dimGrid, dimBlock, 0, stream>>>(
      M, N, K, ptrA, K, ptrB, N, ptrC, N);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemm = load_inline(
    name="cute_tallskinny_gemm",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix multiplication C = A @ B, implemented with a custom CuTe GEMM kernel.
    """
    def __init__(self) -> None:
        super(ModelNew, self).__init__()
        self._ext = cute_gemm

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A.cuda(), B.cuda())

